const ADJACENT_OFFSETS = [-1, 0, 1];

/** The eight cells touching this one on a side or corner — itself excluded. */
const neighboursOf = ([x, y]: Cell): Cell[] =>
  ADJACENT_OFFSETS.flatMap((dx) =>
    ADJACENT_OFFSETS.filter((dy) => dx !== 0 || dy !== 0).map(
      (dy): Cell => [x + dx, y + dy],
    ),
  );

/** Two cells are neighbours when they touch on any side or corner. */
const isNeighbour = (candidate: Cell, cell: Cell): boolean =>
  neighboursOf(cell).some((neighbour) => isSameCell(neighbour, candidate));

const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((candidate) => isNeighbour(candidate, cell)).length;

